mapper.select:
SELECT ds.*,
       op.incident_id,
       pp.phone_code AS police_phone_code,
       pp.display_name AS police_phone_display_name
FROM duty_shift ds
JOIN operational_period op ON op.id = ds.operational_period_id
LEFT JOIN police_phone pp ON pp.id = ds.police_phone_id
LEFT JOIN incident_assignment ia ON ia.id = ds.incident_assignment_id
WHERE op.incident_id = #{incidentId,typeHandler=com.surimap.config.mybatis.UuidTypeHandler}

    AND ds.operational_period_id = #{opId,typeHandler=com.surimap.config.mybatis.UuidTypeHandler}


    AND ds.police_phone_id = #{policePhoneId,typeHandler=com.surimap.config.mybatis.UuidTypeHandler}


    AND ia.account_id = #{accountId,typeHandler=com.surimap.config.mybatis.UuidTypeHandler}


    AND ds.status = #{status}

ORDER BY ds.started_at DESC, ds.id ASC

SELECT ia.id
FROM incident_assignment ia
WHERE ia.incident_id = #{incidentId,typeHandler=com.surimap.config.mybatis.UuidTypeHandler}
  AND ia.account_id = #{accountId,typeHandler=com.surimap.config.mybatis.UuidTypeHandler}
  AND ia.revoked_at IS NULL
LIMIT 1

SELECT COUNT(*)
FROM police_phone pp
WHERE pp.id = #{policePhoneId,typeHandler=com.surimap.config.mybatis.UuidTypeHandler}
  AND pp.account_id = #{accountId,typeHandler=com.surimap.config.mybatis.UuidTypeHandler}
  AND pp.status = 'ACTIVE'
  AND pp.registered = TRUE
